41	// InstallHooks installs Copilot CLI hooks in .github/hooks/entire.json.
42	// If force is true, removes existing Entire hooks before installing.
43	// Returns the number of hooks installed.
44	// Unknown top-level fields and hook types are preserved on round-trip.
45	func (c *CopilotCLIAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
46		worktreeRoot, err := paths.WorktreeRoot(ctx)
47		if err != nil {
48			worktreeRoot = "."
49		}
50	
51		hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
52	
53		// Use raw maps to preserve unknown fields on round-trip
54		var rawFile map[string]json.RawMessage
55		var rawHooks map[string]json.RawMessage
56	
57		existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
58		switch {
59		case readErr == nil:
60			if err := json.Unmarshal(existingData, &rawFile); err != nil {
61				return 0, fmt.Errorf("failed to parse existing %s: %w", HooksFileName, err)
62			}
63			if hooksRaw, ok := rawFile["hooks"]; ok {
64				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
65					return 0, fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
66				}
67			}
68			if _, ok := rawFile["version"]; !ok {
69				rawFile["version"] = json.RawMessage(`1`)
70			}
71		case errors.Is(readErr, os.ErrNotExist):
72			rawFile = map[string]json.RawMessage{
73				"version": json.RawMessage(`1`),
74			}
75		default:
76			return 0, fmt.Errorf("failed to read %s: %w", HooksFileName, readErr)
77		}
78	
79		if rawHooks == nil {
80			rawHooks = make(map[string]json.RawMessage)
81		}
82	
83		// Parse existing entries for each hook type we manage
84		hookEntries := make(map[string][]CopilotHookEntry)
85		for _, hookName := range c.HookNames() {
86			key := hookConfigKey[hookName]
87			var entries []CopilotHookEntry
88			if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
89				return 0, fmt.Errorf("failed to parse %s hooks: %w", key, err)
90			}
91			hookEntries[hookName] = entries
92		}
93	
94		// If force, remove existing Entire hooks first
95		if force {
96			for hookName, entries := range hookEntries {
97				hookEntries[hookName] = removeEntireHooks(entries)
98			}
99		}
100	
101		// Define command prefix
102		var cmdPrefix string
103		if localDev {
104			cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks copilot-cli `
105		} else {
106			cmdPrefix = "entire hooks copilot-cli "
107		}
108	
109		count := 0
110	
111		// Add hooks that don't already exist
112		for _, hookName := range c.HookNames() {
113			cmd := cmdPrefix + hookName
114			if !localDev {
115				cmd = agent.WrapProductionSilentHookCommand(cmd)
116			}
117			entries := hookEntries[hookName]
118			if !hookBashExists(entries, cmd) {
119				entries = append(entries, CopilotHookEntry{
120					Type:    "command",
121					Bash:    cmd,
122					Comment: "Entire CLI",
123				})
124				hookEntries[hookName] = entries
125				count++
126			}
127		}
128	
129		if count == 0 {
130			return 0, nil
131		}
132	
133		// Marshal modified hook types back into rawHooks
134		for _, hookName := range c.HookNames() {
135			key := hookConfigKey[hookName]
136			if err := marshalCopilotHookType(rawHooks, key, hookEntries[hookName]); err != nil {
137				return 0, fmt.Errorf("failed to marshal %s hooks: %w", key, err)
138			}
139		}
140	
141		// Marshal hooks and update raw file
142		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
143		if err != nil {
144			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
145		}
146		rawFile["hooks"] = hooksJSON
147	
148		// Write to file
149		if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
150			return 0, fmt.Errorf("failed to create %s directory: %w", hooksDir, err)
151		}
152	
153		output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
154		if err != nil {
155			return 0, fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
156		}
157	
158		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
159			return 0, fmt.Errorf("failed to write %s: %w", HooksFileName, err)
160		}
161	
162		return count, nil
163	}
