165	// UninstallHooks removes Entire hooks from Copilot CLI's entire.json.
166	// Unknown top-level fields and hook types are preserved on round-trip.
167	func (c *CopilotCLIAgent) UninstallHooks(ctx context.Context) error {
168		worktreeRoot, err := paths.WorktreeRoot(ctx)
169		if err != nil {
170			worktreeRoot = "."
171		}
172		hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
173		data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
174		if err != nil {
175			if errors.Is(err, os.ErrNotExist) {
176				return nil // No hooks file means nothing to uninstall
177			}
178			return fmt.Errorf("failed to read %s: %w", HooksFileName, err)
179		}
180	
181		var rawFile map[string]json.RawMessage
182		if err := json.Unmarshal(data, &rawFile); err != nil {
183			return fmt.Errorf("failed to parse %s: %w", HooksFileName, err)
184		}
185	
186		var rawHooks map[string]json.RawMessage
187		if hooksRaw, ok := rawFile["hooks"]; ok {
188			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
189				return fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
190			}
191		}
192		if rawHooks == nil {
193			rawHooks = make(map[string]json.RawMessage)
194		}
195	
196		// Parse and remove Entire hooks from each hook type we manage
197		for _, hookName := range c.HookNames() {
198			key := hookConfigKey[hookName]
199			var entries []CopilotHookEntry
200			if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
201				return fmt.Errorf("failed to parse %s hooks: %w", key, err)
202			}
203			entries = removeEntireHooks(entries)
204			if err := marshalCopilotHookType(rawHooks, key, entries); err != nil {
205				return fmt.Errorf("failed to marshal %s hooks: %w", key, err)
206			}
207		}
208	
209		// Marshal hooks back (preserving unknown hook types)
210		if len(rawHooks) > 0 {
211			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
212			if err != nil {
213				return fmt.Errorf("failed to marshal hooks: %w", err)
214			}
215			rawFile["hooks"] = hooksJSON
216		} else {
217			delete(rawFile, "hooks")
218		}
219	
220		// Write back
221		output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
222		if err != nil {
223			return fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
224		}
225	
226		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
227			return fmt.Errorf("failed to write %s: %w", HooksFileName, err)
228		}
229		return nil
230	}
