232	// AreHooksInstalled checks if Entire hooks are installed in the Copilot CLI config.
233	func (c *CopilotCLIAgent) AreHooksInstalled(ctx context.Context) bool {
234		worktreeRoot, err := paths.WorktreeRoot(ctx)
235		if err != nil {
236			worktreeRoot = "."
237		}
238		hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
239		data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
240		if err != nil {
241			if !errors.Is(err, os.ErrNotExist) {
242				logging.Warn(ctx, "copilot-cli: failed to read hooks file", "path", hooksPath, "err", err)
243			}
244			return false
245		}
246	
247		var hooksFile CopilotHooksFile
248		if err := json.Unmarshal(data, &hooksFile); err != nil {
249			logging.Warn(ctx, "copilot-cli: failed to parse hooks file", "path", hooksPath, "err", err)
250			return false
251		}
252	
253		return hasEntireHook(hooksFile.Hooks.UserPromptSubmitted) ||
254			hasEntireHook(hooksFile.Hooks.SessionStart) ||
255			hasEntireHook(hooksFile.Hooks.AgentStop) ||
256			hasEntireHook(hooksFile.Hooks.SessionEnd) ||
257			hasEntireHook(hooksFile.Hooks.SubagentStop) ||
258			hasEntireHook(hooksFile.Hooks.PreToolUse) ||
259			hasEntireHook(hooksFile.Hooks.PostToolUse) ||
260			hasEntireHook(hooksFile.Hooks.ErrorOccurred)
261	}
262	
263	// GetSupportedHooks returns the normalized lifecycle events this agent supports.
264	// Note: HookNames() returns 8 hooks but GetSupportedHooks() returns only 6.
265	// The two not listed here are:
266	//   - subagentStop: handled by ParseHookEvent (returns SubagentEnd), but there is no
267	//     HookType constant for subagent events (they use EventType instead).
268	//   - errorOccurred: pass-through hook with no lifecycle action (ParseHookEvent returns nil).
269	func (c *CopilotCLIAgent) GetSupportedHooks() []agent.HookType {
270		return []agent.HookType{
271			agent.HookSessionStart,
272			agent.HookSessionEnd,
273			agent.HookUserPromptSubmit,
274			agent.HookStop,
275			agent.HookPreToolUse,
276			agent.HookPostToolUse,
277		}
278	}
