280	// parseCopilotHookType parses a specific hook type from rawHooks into the target slice.
281	func parseCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CopilotHookEntry) error {
282		if data, ok := rawHooks[hookType]; ok {
283			if err := json.Unmarshal(data, target); err != nil {
284				return fmt.Errorf("invalid JSON for hook type %s: %w", hookType, err)
285			}
286		}
287		return nil
288	}
289	
290	// marshalCopilotHookType marshals a hook type back into rawHooks.
291	// If the slice is empty, removes the key from rawHooks.
292	func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) error {
293		if len(entries) == 0 {
294			delete(rawHooks, hookType)
295			return nil
296		}
297		data, err := jsonutil.MarshalWithNoHTMLEscape(entries)
298		if err != nil {
299			return fmt.Errorf("failed to marshal hook type %s: %w", hookType, err)
300		}
301		rawHooks[hookType] = data
302		return nil
303	}
304	
305	// hookBashExists checks if a hook with the given bash command already exists.
306	func hookBashExists(entries []CopilotHookEntry, bash string) bool {
307		for _, entry := range entries {
308			if entry.Bash == bash {
309				return true
310			}
311		}
312		return false
313	}
314	
315	// isEntireHook checks if a hook entry's bash command belongs to Entire.
316	func isEntireHook(bash string) bool {
317		return agent.IsManagedHookCommand(bash, entireHookPrefixes)
318	}
319	
320	// hasEntireHook checks if any entry in the slice is an Entire hook.
321	func hasEntireHook(entries []CopilotHookEntry) bool {
322		for _, entry := range entries {
323			if isEntireHook(entry.Bash) {
324				return true
325			}
326		}
327		return false
328	}
329	
330	// removeEntireHooks removes all Entire hooks from the slice.
331	func removeEntireHooks(entries []CopilotHookEntry) []CopilotHookEntry {
332		result := make([]CopilotHookEntry, 0, len(entries))
333		for _, entry := range entries {
334			if !isEntireHook(entry.Bash) {
335				result = append(result, entry)
336			}
337		}
338		return result
339	}
