118	// CopilotSession wraps TmuxSession to handle Copilot CLI's dual input modes.
119	// Copilot CLI can be in "Chat" mode (Enter submits) or "Edit" mode (Ctrl+S
120	// submits). After completing a prompt, copilot may return to either mode
121	// non-deterministically. This wrapper detects Edit mode after sending Enter
122	// and falls back to Ctrl+S if needed.
123	type CopilotSession struct {
124		*TmuxSession
125	}
126	
127	func (cs *CopilotSession) Send(input string) error {
128		if err := cs.clearInputLine(); err != nil {
129			return err
130		}
131	
132		preSend := stableContent(cs.Capture())
133	
134		if err := cs.sendOnce(input, preSend); err != nil {
135			return err
136		}
137	
138		// Copilot CLI's autocomplete can non-deterministically trigger during
139		// text input (e.g. a "/" in "docs/red.md" opens the slash-command menu).
140		// If detected, dismiss with Escape, clear the input, and retry once.
141		time.Sleep(300 * time.Millisecond)
142		if isAutocompleteMenu(cs.Capture()) {
143			if err := cs.dismissAutocompleteAndClear(); err != nil {
144				return err
145			}
146			if err := cs.sendOnce(input, stableContent(cs.Capture())); err != nil {
147				return err
148			}
149		}
150	
151		// Copilot can leave behind a stray slash-command invocation between turns.
152		// Only retry if that error appeared in output produced by this submission,
