284	func (c *CopilotCLI) StartSession(ctx context.Context, dir string) (Session, error) {
285		bin, err := exec.LookPath(c.Binary())
286		if err != nil {
287			return nil, fmt.Errorf("agent binary not found: %w", err)
288		}
289	
290		// Forward auth-related env vars into the tmux session. tmux starts a new
291		// shell that doesn't inherit Go's os.Environ(), so without this the
292		// session can lose both token-based auth and local gh/copilot login state.
293		var envArgs []string
294		for _, key := range []string{"COPILOT_GITHUB_TOKEN", "HOME", "TERM", "XDG_CONFIG_HOME", "GH_CONFIG_DIR"} {
295			if v := os.Getenv(key); v != "" {
296				envArgs = append(envArgs, key+"="+v)
297			}
298		}
299		args := append([]string{"env"}, envArgs...)
300		args = append(args, bin, "--model", "claude-haiku-4.5", "--allow-all")
301	
302		name := fmt.Sprintf("copilot-test-%d", time.Now().UnixNano())
303		// Strip CI env vars that may affect interactive mode.
304		unset := []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}
305		s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
306		if err != nil {
307			return nil, err
308		}
309	
310		// Dismiss startup dialogs (folder trust, etc.) then wait for the "❯" prompt.
311		// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
312		// new directories. "Yes" is pre-selected, so Enter dismisses it.
313		foundPrompt := false
314		for range 5 {
315			content, err := s.WaitFor(`(❯|Enter to select)`, 30*time.Second)
316			if err != nil {
317				_ = s.Close()
318				return nil, fmt.Errorf("waiting for startup prompt: %w", err)
319			}
320			if strings.Contains(content, "❯") && !strings.Contains(content, "Enter to select") {
321				foundPrompt = true
322				break
323			}
324			if err := s.SendKeys("Enter"); err != nil {
325				_ = s.Close()
326				return nil, fmt.Errorf("dismissing startup dialog: %w", err)
327			}
328			time.Sleep(500 * time.Millisecond)
329		}
330		if !foundPrompt {
331			_ = s.Close()
332			return nil, errors.New("copilot CLI did not reach interactive prompt after dismissing startup dialogs")
333		}
334		s.stableAtSend = ""
335	
336		return &CopilotSession{TmuxSession: s}, nil
337	}
