18	// RunIsolatedTextGeneratorCLI executes a text-generation CLI in an isolated temp
19	// directory with all GIT_* environment variables removed. This avoids recursive
20	// hook triggers and repo side effects while preserving provider-specific flags.
21	func RunIsolatedTextGeneratorCLI(ctx context.Context, runner TextCommandRunner, binary, displayName string, args []string, stdin string) (string, error) {
22		if runner == nil {
23			runner = exec.CommandContext
24		}
25	
26		cmd := runner(ctx, binary, args...)
27		cmd.Dir = os.TempDir()
28		cmd.Env = StripGitEnv(os.Environ())
29		if stdin != "" {
30			cmd.Stdin = strings.NewReader(stdin)
31		}
32	
33		var stdout, stderr bytes.Buffer
34		cmd.Stdout = &stdout
35		cmd.Stderr = &stderr
36	
37		if err := cmd.Run(); err != nil {
38			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
39				return "", context.DeadlineExceeded
40			}
41			if errors.Is(ctx.Err(), context.Canceled) {
42				return "", context.Canceled
43			}
44			var execErr *exec.Error
45			if errors.As(err, &execErr) {
46				return "", fmt.Errorf("%s CLI not found: %w", displayName, err)
47			}
48			var exitErr *exec.ExitError
49			if errors.As(err, &exitErr) {
50				detail := strings.TrimSpace(stderr.String())
51				if detail == "" {
52					detail = strings.TrimSpace(stdout.String())
53				}
54				if detail == "" {
55					detail = err.Error()
56				}
57				return "", fmt.Errorf("%s CLI failed (exit %d): %s: %w", displayName, exitErr.ExitCode(), detail, err)
58			}
59			return "", fmt.Errorf("failed to run %s CLI: %w", displayName, err)
60		}
61	
62		result := strings.TrimSpace(stdout.String())
63		if result == "" {
64			return "", fmt.Errorf("%s CLI returned empty output", displayName)
65		}
66		return result, nil
67	}
