47	// SetupRepo creates a fresh git repository in a temporary directory, seeds it
48	// with an initial commit, and runs `entire enable` for the given agent.
49	// Artifact capture is registered as a cleanup function.
50	//
51	// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
52	// so it can be inspected after the test. A symlink in the artifact dir
53	// points to the preserved repo.
54	func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
55		t.Helper()
56	
57		keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""
58	
59		// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
60		// creates nested subdirectories (TestName.../001/) whose structure
61		// confuses some agents' (e.g. opencode) working-directory resolution.
62		//
63		// Codex refuses to operate from /tmp (e.g. "Refusing to create helper
64		// binaries under temporary dir"), so for codex we place the repo under
65		// $HOME/.cache/entire-e2e-repos/ instead.
66		root := ""
67		if agent.Name() == "codex" {
68			cache, cerr := os.UserCacheDir()
69			if cerr != nil {
70				t.Fatalf("resolve user cache dir: %v", cerr)
71			}
72			root = filepath.Join(cache, "entire-e2e-repos")
73			if err := os.MkdirAll(root, 0o755); err != nil {
74				t.Fatalf("create e2e repo root %q: %v", root, err)
75			}
76		}
77		dir, err := os.MkdirTemp(root, "e2e-repo-*")
78		if err != nil {
79			t.Fatalf("create temporary e2e repo under %q: %v", root, err)
80		}
81		if keepRepos {
82			t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
83		} else {
84			t.Cleanup(func() { os.RemoveAll(dir) })
85		}
86	
87		// Resolve symlinks (macOS: /var -> /private/var) so paths match
88		// what agent CLIs see when they resolve their own CWD.
89		if resolved, err := filepath.EvalSymlinks(dir); err == nil {
90			dir = resolved
91		}
92	
93		Git(t, dir, "init")
94		Git(t, dir, "config", "user.name", "E2E Test")
