96	func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
97		cfg := &runConfig{}
98		for _, o := range opts {
99			o(cfg)
100		}
101	
102		timeout := 90 * time.Second
103		if cfg.PromptTimeout > 0 {
104			timeout = cfg.PromptTimeout
105		}
106	
107		displayCmd := a.Binary() + " --force --workspace " + dir + " (interactive prompt: " + prompt + ")"
108	
109		// Start an interactive tmux session so all hooks fire
110		// (beforeSubmitPrompt and stop don't fire in headless -p mode).
111		s, err := a.startInteractiveSession(dir)
112		if err != nil {
113			return Output{Command: displayCmd, ExitCode: -1},
114				fmt.Errorf("start interactive session: %w", err)
115		}
116		defer s.Close()
117	
118		// Wait for trust dialog and accept it.
119		if err := a.acceptTrustDialogIfNeeded(s); err != nil {
120			return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1}, err
121		}
122	
