172	// startInteractiveSession creates a new tmux session running the Cursor CLI
173	// in interactive mode (no -p flag) so all hooks fire.
174	func (a *CursorCLI) startInteractiveSession(dir string) (*TmuxSession, error) {
175		// Resolve to absolute path so tmux can find the binary even if its
176		// shell doesn't inherit the test process's PATH (common on CI).
177		bin, err := exec.LookPath(a.Binary())
178		if err != nil {
179			return nil, fmt.Errorf("agent binary not found: %w", err)
180		}
181	
182		// Create an isolated config directory for this session so parallel tests
183		// don't race on the shared ~/.config/cursor/cli-config.json file.
184		configDir, err := cursorConfigDir()
185		if err != nil {
186			return nil, fmt.Errorf("create cursor config dir: %w", err)
187		}
188	
189		// Build env-wrapped command so the tmux session inherits critical env vars.
190		// tmux starts a new shell that doesn't inherit Go's os.Environ().
191		var envArgs []string
192		for _, key := range []string{"CURSOR_API_KEY", "PATH", "HOME", "TERM"} {
193			if v := os.Getenv(key); v != "" {
194				envArgs = append(envArgs, key+"="+v)
195			}
196		}
197		// Point XDG_CONFIG_HOME to our isolated dir so cursor writes its config
198		// there instead of ~/.config/cursor/. We keep the real HOME so that
199		// auth credentials (keychain, OAuth tokens) remain accessible.
200		envArgs = append(envArgs, "XDG_CONFIG_HOME="+configDir)
201	
202		args := append([]string{"env"}, envArgs...)
203		args = append(args, bin, "--force", "--workspace", dir)
204	
205		name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
206		unset := []string{"CI"}
207		s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
208		if err != nil {
209			_ = os.RemoveAll(configDir)
210			return nil, err
211		}
212		s.OnClose(func() { _ = os.RemoveAll(configDir) })
213		return s, nil
214	}
