104	// AgentForTranscriptPath returns the registered agent whose session directory
105	// for repoPath contains the given transcript path. Used to disambiguate which
106	// agent owns a session when multiple agents' hooks fire for the same session
107	// ID — a Cursor transcript path uniquely identifies a Cursor session even
108	// when Claude Code's hook is the one firing.
109	//
110	// Returns (nil, false) if transcriptPath is empty, no agent claims it, or any
111	// registry lookup fails. Match is by directory prefix (with a separator) so
112	// "/x/.claude/projects/abc.jsonl" doesn't accidentally match an agent rooted
113	// at "/x/.claude/projects/ab".
114	//
115	//nolint:revive // AgentForTranscriptPath: stutter is intentional for package callers (agent.AgentForTranscriptPath reads naturally)
116	func AgentForTranscriptPath(transcriptPath, repoPath string) (Agent, bool) {
117		if transcriptPath == "" {
118			return nil, false
119		}
120		abs, err := filepath.Abs(transcriptPath)
121		if err != nil {
122			abs = transcriptPath
123		}
124		for _, name := range List() {
125			ag, err := Get(name)
126			if err != nil {
127				continue
128			}
129			dir, err := ag.GetSessionDir(repoPath)
130			if err != nil || dir == "" {
131				continue
132			}
133			dirAbs, err := filepath.Abs(dir)
134			if err != nil {
135				dirAbs = dir
136			}
137			if pathHasDirPrefix(abs, dirAbs) {
138				return ag, true
139			}
140		}
141		return nil, false
142	}
143	
144	// pathHasDirPrefix reports whether path is contained within dir (or equals it).
145	// Adds a trailing separator before prefix-matching so /a/bc doesn't match /a/b.
146	//
147	// On Windows, comparison is case-insensitive: NTFS/ReFS treat paths as
148	// case-insensitive, and filepath.Abs preserves whatever casing the input had,
149	// so a transcript path like `C:\Users\Bob\.cursor\...` and a session dir like
150	// `c:\users\bob\.cursor\...` refer to the same location but would not match
151	// under a byte-wise comparison.
152	func pathHasDirPrefix(path, dir string) bool {
153		if runtime.GOOS == "windows" {
154			path = strings.ToLower(path)
155			dir = strings.ToLower(dir)
156		}
157		if path == dir {
158			return true
159		}
160		if !strings.HasSuffix(dir, string(filepath.Separator)) {
161			dir += string(filepath.Separator)
162		}
163		return strings.HasPrefix(path, dir)
164	}
